import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { claimsKey } from '../claims/useClaims';
import { peopleKey } from '../people/usePeople';
import { plansKey } from './usePlans';

// The generate button: for every plan on the sheet, in the order they were added, a DRAFT claim of the
// plan's amount for each plan date (the start, then every N days) up to the end and the sheet's today that
// has none yet, dated that day with an empty note. A date the claim form refuses is skipped and tried
// again next time. Shows how many were made; pressing again removes the old count until the new one is in.
export function GeneratePlans() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const generate = useMutation({
    mutationFn: () => postJson<{ made: number }>(`/api/sheets/${encodeURIComponent(sheet)}/plans/generate`, { user }),
    onSuccess: () => {
      // Not awaited: the count shows as soon as the claims are in, never after the rows it made.
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      void queryClient.invalidateQueries({ queryKey: plansKey(sheet) });
    },
  });

  return (
    <p>
      <button
        type="button"
        data-testid="plan-generate"
        onClick={() =>
          once(() => {
            generate.reset();
            return generate.mutateAsync();
          })
        }
      >
        Generate plan claims
      </button>
      {generate.isSuccess && (
        <>
          {' '}
          Made <span data-testid="plan-generated-count">{generate.data.made}</span>
        </>
      )}
      {generate.isError && (
        <span data-testid="plan-generate-error" role="alert">
          {' '}
          The plans' claims could not be generated.
        </span>
      )}
    </p>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { usePersonAction } from '../people/usePersonAction';
import { plansKey, usePlans, type Plan } from './usePlans';

// The person's plans, each with how many claims it has made so far and its next five dates after the sheet's today, and the form that adds one: an amount
// the claim form takes, a start (blank: the sheet's today), every N days (a whole number, at least 1) or
// instead monthly on a day of the month (1 to 31), and an end not before the start. A refusal shows the plan error on the row.
export function PlanControl({ personId }: { personId: string }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const plans = usePlans(sheet).filter((p) => p.personId === personId);
  const [amount, setAmount] = useState('');
  const [start, setStart] = useState('');
  const [every, setEvery] = useState('');
  const [day, setDay] = useState('');
  const [end, setEnd] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { amount: string; start: string; every: string; day: string; end: string }) =>
      postJson<Plan>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/plans`, { ...body, user }),
    onSuccess: () => {
      setAmount('');
      setStart('');
      setEvery('');
      setDay('');
      setEnd('');
      return queryClient.invalidateQueries({ queryKey: plansKey(sheet) });
    },
  });
  const taken = usePersonAction(personId, () => add.reset());
  const changed = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    add.reset();
  };

  return (
    <div>
      <ul>
        {plans.map((p) => (
          <li key={p.id} data-testid={`plan-row-${p.id}`}>
            <span data-testid="plan-amount-shown">{p.amount}</span>{' '}
            {p.day !== null ? (
              <>
                monthly on day <span data-testid="plan-day">{p.day}</span>
              </>
            ) : (
              <>
                every <span data-testid="plan-every">{p.every}</span> days
              </>
            )}{' '}
            from{' '}
            <span data-testid="plan-start">{p.start}</span> to <span data-testid="plan-end">{p.end}</span>, made{' '}
