import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("plan pause", () => {
  test("plan pause", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "10.00", "start": "2026-03-01", "end": "2026-03-20", "every": "2"}));
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
    await ui.setToday(pg_uma, "2026-03-04");
    expect(await ui.planPause(pg_uma, pl_ada_1, true)).toBe(true);
    expect(await ui.planPause(pg_uma, pl_ada_1, true)).toBe(false);
    await ui.setToday(pg_uma, "2026-03-08");
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_ada_1 = await ui.claimAt(pg_uma, p_ada, 1);
    expect(await ui.planPause(pg_uma, pl_ada_1, false)).toBe(true);
    expect(await ui.planPause(pg_uma, pl_ada_1, false)).toBe(false);
    await ui.setToday(pg_uma, "2026-03-12");
    expect(await ui.generatePlans(pg_uma)).toBe(2);
    const c_ada_2 = await ui.claimAt(pg_uma, p_ada, 2);
    const c_ada_3 = await ui.claimAt(pg_uma, p_ada, 3);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-date")).toHaveText("2026-03-11");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-date")).toHaveText("2026-03-09");
